function taskCount(r,date=boundaryDate()){if(!r)return 0;const friday=new Date(date+'T12:00:00').getDay()===5;return ['fajr','dhuhr','asr','maghrib','isha'].filter(k=>r.prayers[k]).length+(r.quran>=7?1:0)+(friday||r.salawat>=100?1:0)+(r.istighfar>=100?1:0)+(r.dhikr>=100?1:0)+(r.muraqaba>=10?1:0)}
