 const sunnah=all.reduce((n,[,r])=>n+Object.values(r.sunnah||{}).filter(Boolean).length,0),nafl=all.reduce((n,[,r])=>n+Object.values(r.nafl||{}).filter(Boolean).length,0);
 const mem=all.filter(([,r])=>r.quranStudy?.memorised).length,rev=all.filter(([,r])=>r.quranStudy?.revised).length;
 const fasts=all.filter(([,r])=>r.fasting?.done).length,dhikr=all.reduce((n,[,r])=>n+(Number(r.dhikr)||0),0),muraqaba=all.reduce((n,[,r])=>n+(Number(r.muraqaba)||0),0);
 const sleep=all.map(([d,r])=>sleepDurationMinutes(state.healthLogs?.[d]?.bedtime||r.bedtime,state.healthLogs?.[d]?.wakeup||r.wakeup)).filter(x=>x!==null),avg=sleep.length?Math.round(sleep.reduce((a,b)=>a+b,0)/sleep.length):null;
 const commitments=all.filter(([,r])=>r.commitments&&(r.commitments.worship||r.commitments.discipline||r.commitments.personal)),honoured=commitments.filter(([,r])=>r.commitments.honoured).length;
