function bytesToB64(bytes){let s='';bytes.forEach(b=>s+=String.fromCharCode(b));return btoa(s)}
function b64ToBytes(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function pinKey(pin,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptBadHabits(data,pin){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await pinKey(pin,salt),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(data)));return {version:1,salt:bytesToB64(salt),iv:bytesToB64(iv),cipher:bytesToB64(new Uint8Array(cipher))}}
async function decryptBadHabits(vault,pin){const key=await pinKey(pin,b64ToBytes(vault.salt)),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(vault.iv)},key,b64ToBytes(vault.cipher));return JSON.parse(new TextDecoder().decode(plain))}

function habitLogValue(log){return typeof log==='number'?Math.max(0,Number(log)||0):Math.max(0,Number(log?.count)||0);}
function habitPeriodSummary(h,start,end){const logs=h.logs||{};let total=0,zero=0,days=0,lapses=0;for(let d=start;d<=end;d=shiftDate(d,1)){if(Object.prototype.hasOwnProperty.call(logs,d)){days++;const n=habitLogValue(logs[d]);total+=n;if(n===0)zero++;else lapses++;}}return {total,zero,days,lapses};}
function habitReductionPercent(h,summary){const baseline=Number(h.baselineDaily);return summary.days&&Number.isFinite(baseline)&&baseline>0?Math.round((1-summary.total/(baseline*summary.days))*100):null;}
function habitAbstinenceStreak(h,endDate){let n=0,d=endDate,logs=h.logs||{};while(Object.prototype.hasOwnProperty.call(logs,d)&&habitLogValue(logs[d])===0){n++;d=shiftDate(d,-1);}return n;}
function renderBadHabitsLock(){const locked=$('badHabitsLocked'),unlocked=$('badHabitsUnlocked'),confirm=$('badHabitsPinConfirmWrap');if(!locked)return;locked.hidden=badHabitsUnlocked;unlocked.hidden=!badHabitsUnlocked;confirm.hidden=!!state.badHabitsVault;$('badHabitsLockMessage').textContent=state.badHabitsVault?'Enter your PIN to unlock your encrypted private vault.':'Create a 8–12 digit PIN. Your entries will be encrypted on this device.';if(badHabitsUnlocked){if($('habitLogDate')&&!$('habitLogDate').value)$('habitLogDate').value=boundaryDate();renderBadHabitsList();}}
function renderBadHabitsList(){
 const host=$('badHabitsList');if(!host)return;
 const date=$('habitLogDate')?.value||boundaryDate();
 host.innerHTML=badHabitsData.map((h,i)=>{const streak=habitAbstinenceStreak(h,date);const count=Object.keys(h.logs||{}).length;return `<article class="private-habit-card"><div class="row-between"><b>${escapeHtml(h.name)}</b><div class="habit-actions"><span class="date-pill">${streak} tracked zero-day streak</span><button class="quiet" data-delete-habit="${i}" aria-label="Delete ${escapeHtml(h.name)}">Delete</button></div></div><p><small>Unit: ${escapeHtml(h.unit||'count')} · Baseline: ${h.baselineDaily===null||h.baselineDaily===undefined?'not set':escapeHtml(String(h.baselineDaily))+' / day'}</small></p><p>${escapeHtml(h.why||'Your reason for quitting has not been added yet.')}</p><p><small>Trigger: ${escapeHtml(h.trigger||'Not specified')}</small></p><p>${escapeHtml(h.replacement||'Add a concrete replacement action.')}</p><div class="habit-tallies"><span>${count} days recorded</span><span>${Object.values(h.logs||{}).filter(x=>habitLogValue(x)===0).length} zero-count days</span><span>${Object.values(h.logs||{}).filter(x=>habitLogValue(x)>0).length} lapse days logged</span></div></article>`}).join('')||'<p class="empty">No habits added yet. Start with one behaviour you want to change.</p>';
 renderHabitDailyBoard();
}
function renderHabitDailyBoard(){
 const host=$('badHabitDailyBoard');if(!host||!badHabitsUnlocked)return;
 const date=$('habitLogDate').value||boundaryDate();$('habitLogDate').value=date;
 host.innerHTML=badHabitsData.map((h,i)=>{const raw=(h.logs||{})[date],log=typeof raw==='object'&&raw?raw:{count:typeof raw==='number'?raw:'',urge:'',triggerNote:'',copingAction:'',replacementUsed:false};return `<article class="private-habit-card"><div class="row-between"><b>${escapeHtml(h.name)}</b><small>${escapeHtml(h.unit||'count')}</small></div><p class="hint">${escapeHtml(h.why||'Why this change matters to you')}</p><div class="two-fields"><div class="field"><label for="habitCount${i}">Count for ${escapeHtml(date)} (enter 0 if none)</label><input id="habitCount${i}" type="number" min="0" max="100000" step="1" inputmode="numeric" value="${Number.isInteger(Number(log.count))&&Number(log.count)>=0&&Number(log.count)<=100000?Number(log.count):''}" placeholder="Daily count"></div><div class="field"><label for="habitUrge${i}">Strongest urge (0–10)</label><input id="habitUrge${i}" type="number" min="0" max="10" step="1" inputmode="numeric" value="${Number.isInteger(Number(log.urge))&&Number(log.urge)>=0&&Number(log.urge)<=10?Number(log.urge):''}" placeholder="0 to 10"></div></div><div class="field"><label for="habitTriggerNote${i}">What triggered it today?</label><input id="habitTriggerNote${i}" maxlength="180" value="${escapeHtml(log.triggerNote||'')}" placeholder="Time, emotion, place or situation"></div><div class="field"><label for="habitCoping${i}">What did you do instead / what will you do next?</label><input id="habitCoping${i}" maxlength="240" value="${escapeHtml(log.copingAction||'')}" placeholder="Walk away, call someone, make wudu, change room…"></div><label class="check-inline"><input id="habitReplacement${i}" type="checkbox" ${log.replacementUsed?'checked':''}> I used my replacement action</label><div class="habit-actions"><button class="secondary" data-habit-zero="${i}">Record 0 · stayed away</button><button class="primary" data-save-habit-log="${i}">Save daily check-in</button></div></article>`}).join('')||'<p class="empty">Add a habit above to start daily accountability.</p>';
 const now=new Date(date+'T12:00:00'),weekStart=new Date(now);weekStart.setDate(now.getDate()-((now.getDay()+6)%7));const ws=localDate(weekStart),we=shiftDate(ws,6),ms=date.slice(0,7)+'-01',me=shiftDate(shiftDate(ms,31),-1);
 let wt=0,wz=0,mt=0,mz=0,parts=[];
 badHabitsData.forEach(h=>{const w=habitPeriodSummary(h,ws,we),m=habitPeriodSummary(h,ms,me);wt+=w.days;wz+=w.zero;mt+=m.days;mz+=m.zero;const reduction=habitReductionPercent(h,w);const baselineText=reduction===null?'':' · '+(reduction>=0?reduction+'% below baseline':Math.abs(reduction)+'% above baseline');parts.push(`<article class="report-card"><small>${escapeHtml(h.name)} · this week / month</small><strong>${w.total} ${escapeHtml(h.unit||'count')} / ${m.total} ${escapeHtml(h.unit||'count')}</strong><small>Tracked days: ${w.days} / ${m.days} · Zero days: ${w.zero} / ${m.zero} · Lapse days: ${w.lapses} / ${m.lapses}</small><small>Tracked zero-day streak: ${habitAbstinenceStreak(h,date)}${baselineText}</small></article>`)});
 $('habitWeekTotal').textContent=wt;$('habitWeekZero').textContent=wz;$('habitMonthTotal').textContent=mt;$('habitMonthZero').textContent=mz;$('habitMonthlyBreakdown').innerHTML=parts.join('');
}
async function saveHabitDailyLog(i,forceZero=false){
 if(!badHabitsUnlocked||!badHabitsData[i])return;
 const date=$('habitLogDate').value||boundaryDate(),input=$('habitCount'+i),value=forceZero?0:Number(input?.value),urgeInput=$('habitUrge'+i),urge=urgeInput?.value===''?null:Number(urgeInput?.value);
 if(!validDate(date)||(!forceZero&&(input?.value===''||!Number.isInteger(value)||value<0||value>100000))||(urge!==null&&(!Number.isInteger(urge)||urge<0||urge>10))){notify('Enter a whole-number count of 0 or more, an urge rating from 0 to 10, and a valid date.');return}
 if(forceZero)input.value='0';
 const h=badHabitsData[i];h.logs=h.logs||{};h.logs[date]={count:value,urge,triggerNote:$('habitTriggerNote'+i).value.trim().slice(0,180),copingAction:$('habitCoping'+i).value.trim().slice(0,240),replacementUsed:$('habitReplacement'+i).checked,updatedAt:new Date().toISOString()};
 await saveBadHabitsVault();renderBadHabitsList();$('habitFeedback').textContent=urge!==null&&urge>=7?'High urge recorded. Change your environment now, use the replacement action you chose, and contact a trusted support person if that helps.':value===0?'Zero recorded. You protected this day. Keep the next step small and repeatable.':`Recorded ${value} ${h.unit||'count'}. A lapse does not erase previous zero days. Identify the trigger, adjust your plan and restart with the next decision.`;notify(value===0?'Abstinence day recorded privately.':'Lapse recorded privately. Review the trigger and restart.');
}
