function healthDay(date=boundaryDate()){
 const d=date;state.healthLogs=state.healthLogs||{};
 if(!state.healthLogs[d])state.healthLogs[d]={taken:{},walk:false,strength:false,mobility:false,focus:false,exerciseMinutes:0,focusMinutes:0,weight:'',note:'',bedtime:'',wakeup:''};
 else state.healthLogs[d]={taken:{},walk:false,strength:false,mobility:false,focus:false,exerciseMinutes:0,focusMinutes:0,weight:'',note:'',bedtime:'',wakeup:'',...state.healthLogs[d]};
 return state.healthLogs[d];
}
function sleepDurationMinutes(bedtime,wakeup){
 const valid=t=>/^([01]\d|2[0-3]):[0-5]\d$/.test(String(t||''));
 if(!valid(bedtime)||!valid(wakeup)||bedtime===wakeup)return null;
 const [bh,bm]=bedtime.split(':').map(Number),[wh,wm]=wakeup.split(':').map(Number);
 let mins=(wh*60+wm)-(bh*60+bm);if(mins<0)mins+=1440;
 return mins>0&&mins<1440?mins:null;
}
function formatSleepDuration(mins){return mins===null||mins===undefined?'—':`${Math.floor(mins/60)}h ${mins%60}m`;}
function renderSleepHistory(){
 const date=boundaryDate(),today=healthDay(date),duration=sleepDurationMinutes(today.bedtime,today.wakeup);
 $('bedtime').value=today.bedtime||'';$('wakeup').value=today.wakeup||'';
 $('sleepDurationToday').textContent=formatSleepDuration(duration);
 const days=Object.entries(state.healthLogs||{}).filter(([d,v])=>d<=date&&sleepDurationMinutes(v.bedtime,v.wakeup)!==null).sort(([a],[b])=>b.localeCompare(a));
 const todayDate=new Date(date+'T12:00:00'),weekStart=new Date(todayDate);weekStart.setDate(todayDate.getDate()-6);
 const weekRows=days.filter(([d])=>d>=localDate(weekStart)).slice(0,7);
 const avg=weekRows.length?Math.round(weekRows.reduce((n,[,v])=>n+sleepDurationMinutes(v.bedtime,v.wakeup),0)/weekRows.length):null;
 $('sleepAverageHealth').textContent=formatSleepDuration(avg);
 const month=date.slice(0,7),monthRows=days.filter(([d])=>d.slice(0,7)===month);
 $('sleepNightsTracked').textContent=monthRows.length;
 $('sleepSummary').textContent=duration!==null?`You recorded ${formatSleepDuration(duration)} of sleep for ${date}. Keep a steady sleep and wake routine.`:'Enter both times to calculate tonight’s sleep duration.';
 $('sleepHistory').innerHTML=days.slice(0,14).map(([d,v])=>`<article class="sleep-history-row"><div><b>${escapeHtml(d)}</b><small>Bed ${escapeHtml(v.bedtime)} · Out of bed ${escapeHtml(v.wakeup)}</small></div><strong>${formatSleepDuration(sleepDurationMinutes(v.bedtime,v.wakeup))}</strong></article>`).join('')||'<p class="empty">Your sleep history will appear here after you save your first complete night.</p>';
}
function renderHealth(){
 const d=boundaryDate(),r=healthDay();$('healthDateLabel').textContent=d;
 $('medicineList').innerHTML=(state.healthPlan||[]).map((m,i)=>`<article class="medicine-row"><div class="row-between"><div><b>${escapeHtml(m.name)}</b><small>${escapeHtml(m.dose||'Follow label / clinician instructions')} · ${escapeHtml(m.time||'No time set')}</small></div><button class="quiet" data-remove-med="${i}">Remove</button></div><label class="task-row"><span class="task-name">Today's status</span><select data-med-status="${i}"><option value="pending" ${!r.taken?.[m.id]||r.taken?.[m.id]==='pending'?'selected':''}>Not recorded</option><option value="taken" ${r.taken?.[m.id]==='taken'?'selected':''}>Taken</option><option value="missed" ${r.taken?.[m.id]==='missed'?'selected':''}>Missed / skipped</option></select></label></article>`).join('')||'<p class="empty">Add your daily medicines and supplements above.</p>';
 $('exerciseWalk').checked=!!r.walk;$('exerciseStrength').checked=!!r.strength;$('exerciseMobility').checked=!!r.mobility;$('exerciseFocus').checked=!!r.focus;$('exerciseMinutes').value=r.exerciseMinutes||'';$('focusMinutes').value=r.focusMinutes||'';$('weightEntry').value=r.weight||'';$('exerciseNote').value=r.note||'';
 const days=Object.entries(state.healthLogs||{}).sort(([a],[b])=>a.localeCompare(b));const weekStart=new Date(d+'T12:00:00');weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));const ws=localDate(weekStart),we=shiftDate(ws,6),ms=d.slice(0,7)+'-01',me=shiftDate(shiftDate(ms,31),-1),within=(x,a,b)=>x>=a&&x<=b;
 const weekly=days.filter(([date])=>within(date,ws,we)).map(([,v])=>v),monthly=days.filter(([date])=>within(date,ms,me)).map(([,v])=>v);
 $('medWeekTotal').textContent=weekly.reduce((n,v)=>n+Object.values(v.taken||{}).filter(x=>x==='taken'||x==='missed').length,0);$('medWeekMissed').textContent=weekly.reduce((n,v)=>n+Object.values(v.taken||{}).filter(x=>x==='missed').length,0);$('moveWeekTotal').textContent=weekly.reduce((n,v)=>n+(Number(v.exerciseMinutes)||0),0);$('focusWeekTotal').textContent=weekly.reduce((n,v)=>n+(Number(v.focusMinutes)||0),0);$('exerciseMonthDays').textContent=monthly.filter(v=>v.walk||v.strength||v.mobility).length;
 $('healthSummary').innerHTML=`<span>Medicines on plan: <b>${(state.healthPlan||[]).length}</b></span><span>Today's movement: <b>${r.exerciseMinutes||0} min</b></span><span>Today's focus: <b>${r.focusMinutes||0} min</b></span>`;
renderSleepHistory();}
function addMedicine(){const name=$('medName').value.trim();if(!name){notify('Enter a medicine or supplement name.');return}state.healthPlan=state.healthPlan||[];state.healthPlan.push({id:'med-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name,dose:$('medDose').value.trim(),time:$('medTime').value||'',createdAt:localDate()});save();$('medName').value='';$('medDose').value='';renderHealth();notify('Added to your daily health routine.')}
function saveHealthDay(){const r=healthDay();r.walk=$('exerciseWalk').checked;r.strength=$('exerciseStrength').checked;r.mobility=$('exerciseMobility').checked;r.focus=$('exerciseFocus').checked;r.exerciseMinutes=clamp($('exerciseMinutes').value,0,300);r.focusMinutes=clamp($('focusMinutes').value,0,300);const w=$('weightEntry').value.trim();r.weight=w?Math.max(25,Math.min(350,Number(w))):'';r.note=$('exerciseNote').value.trim().slice(0,300);save();renderHealth();renderInsights();notify('Health and movement record saved.')}
